create extension if not exists pgcrypto;
create table if not exists public.mail_accounts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,provider text not null,email text not null,provider_account_id text not null,access_token_enc text,refresh_token_enc text not null,token_expires_at timestamptz,scopes text[] not null default '{}',sync_status text not null default 'pending',last_synced_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,provider,provider_account_id));
create table if not exists public.email_messages(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,account_id uuid not null references public.mail_accounts(id) on delete cascade,provider text not null,provider_message_id text not null,thread_id text,subject text,sender_name text,sender_email text,recipients text,snippet text,body_text text,body_html text,received_at timestamptz,is_read boolean not null default false,raw_headers jsonb not null default '[]'::jsonb,created_at timestamptz not null default now(),unique(account_id,provider_message_id));
create index if not exists email_messages_user_received_idx on public.email_messages(user_id,received_at desc);
alter table public.mail_accounts enable row level security;alter table public.email_messages enable row level security;
create policy "Users manage own mail accounts" on public.mail_accounts for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
create policy "Users read own email messages" on public.email_messages for select to authenticated using((select auth.uid())=user_id);
grant select on public.mail_accounts,public.email_messages to authenticated;
